 join public.disease_orpha_mappings m
 on m.disease_id=p.disease_id and m.orpha_code=p.orpha_code
), counted as (select count(*) as n from verified)
insert into public.disease_clinical_embedding_pilot
 (disease_id,x,y,z,fcm_cluster,membership,annotated_hpo,annotated_causal_genes,model_version)
select disease_id,x,y,z,fcm_cluster,membership,annotated_hpo,annotated_causal_genes,model_version
from verified where (select n from counted)=120
on conflict(disease_id) do update set
 x=excluded.x,y=excluded.y,z=excluded.z,
 fcm_cluster=excluded.fcm_cluster,membership=excluded.membership,
 annotated_hpo=excluded.annotated_hpo,
 annotated_causal_genes=excluded.annotated_causal_genes,
 model_version=excluded.model_version;

-- Make private staging metadata agree with already corroborated independent mappings.
update public.disease_orpha_evidence_staging s set review_status='reviewed'
from public.disease_orpha_mappings m
where m.disease_id=s.disease_id and m.orpha_code=s.orpha_code
and s.review_status='unreviewed';
